{
  "command": "cd "$PWD"; ceridwen/.venv/bin/python - <<'EOF'
import h5py, numpy as np
from scipy.special import softmax
runs = {
 "kcbump (default dust priors)": "results/m1-210210-kcbump-2026-09-29/run/fits",
 "wide": "results/m1-210210-kcbump-wide-2026-09-29/run/fits",
 "neb_eline_ca_nohe_zevo": "results/m1-210210-neb-eline-ca-nohe-zevo-2026-09-30/run/fits",
}
import glob
def wq(x, w, qs):
    i = np.argsort(x); c = np.cumsum(w[i]); c /= c[-1]
    return [x[i][np.searchsorted(c, q)] for q in qs]
for name, d in runs.items():
    for p in glob.glob(d + "/*/*/ceridwen_result.h5"):
        f = h5py.File(p); s = f["samples"]; w = softmax(s["log_weights"][:])
        print("==", name, p.split("/fits/")[1])
        for k in ["diffuse_tau_noll", "diffuse_delta", "diffuse_Ebump", "dust_ratio", "log_f_calib", "Z", "afe", "zh_beta_unit", "logmass", "sigma_smooth"]:
            if k in s:
                x = s[k][:]
                print(f"  {k:18s} 1/16/50/84/99 %:", np.round(wq(x, w, [.01,.16,.5,.84,.99]), 3), " min/max", np.round([x.min(), x.max()], 3))
EOF",
  "description": "Compute posterior quantiles against prior bounds"
}

